"""MXFP4 fused MoE in FlyDSL: decode token counts run two route-direct launches; larger ones run aiter's two-stage
pipeline around a FlyDSL routing sort, a fused first-block stage 1 and an expert-stationary MXFP4 stage 2 whose
route partials a FlyDSL reduction adds in route order."""

import functools

import flydsl.compiler as flyc
import flydsl.expr as fx
import torch
from aklr.ops.fused_moe.baseline import fused_moe_baseline
from flydsl._mlir import ir
from flydsl._mlir.dialects import arith, llvm
from flydsl._mlir.dialects import rocdl as rocdl_ods
from flydsl._mlir.extras import types as _T
from flydsl.expr import const_expr, gpu, range_constexpr, rocdl
from flydsl.expr.typing import T
from flydsl.runtime.device import is_rdna_arch

_D = 6144  # model dim
_I = 512  # inter dim
_N1 = 2 * _I  # gate + up rows
_TOPK = 9


def _raw(v):
    if not isinstance(v, ir.Value) and hasattr(v, "ir_value"):
        return v.ir_value()
    return v


def _rsrc(addr, nbytes=None):
    """Buffer resource over a raw device address: no bounds checking, or accesses at or past ``nbytes`` dropped."""
    flags = (7 << 12) | (4 << 15)
    if is_rdna_arch(None):
        flags |= (1 << 24) | (2 << 28)
    base = llvm.IntToPtrOp(ir.Type.parse("!llvm.ptr"), _raw(fx.Int64(addr))).result
    i32 = _T.i32()
    i16 = _T.i16()
    i64 = _T.i64()
    fl = arith.ConstantOp(i32, ir.IntegerAttr.get(i32, flags)).result
    stride = arith.ConstantOp(i16, ir.IntegerAttr.get(i16, 0)).result
    if nbytes is None:
        nrec = arith.ConstantOp(i64, ir.IntegerAttr.get(i64, 0xFFFFFFFF)).result
    else:
        nrec = arith.extui(i64, _raw(fx.Int32(nbytes)))
    return rocdl_ods.MakeBufferRsrcOp(ir.Type.parse("!llvm.ptr<8>"), base, stride, nrec, fl).result


def _ld4(rsrc, off):
    return fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x4, rsrc, fx.Int32(off), fx.Int32(0)))


def _ld1(rsrc, off):
    return fx.Int32(rocdl.raw_ptr_buffer_load(T.i32, rsrc, fx.Int32(off), fx.Int32(0)))


def _st(rsrc, off, value):
    rocdl_ods.raw_ptr_buffer_store(_raw(value), rsrc, _raw(fx.Int32(off)), _raw(fx.Int32(0)))


def _st16(rsrc, off, value):
    _st(rsrc, off, arith.trunci(T.i16, _raw(fx.Int32(value))))


def _uniform(x):
    return fx.Int32(rocdl.readfirstlane(T.i32, _raw(fx.Int32(x))))


def _sload(addr, idx):
    """Scalar (SMEM) load of the i32 at addr + 4 * idx for a workgroup-uniform idx."""
    ptr = llvm.IntToPtrOp(ir.Type.parse("!llvm.ptr<4>"), _raw(fx.Int64(addr) + fx.Int64(idx) * 4)).result
    return fx.Int32(llvm.LoadOp(T.i32, ptr, alignment=4, invariant=True).res)


def _lds(base, off):
    ptr_ty = fx.PointerType.get(T.i8, fx.AddressSpace.Shared)
    return fx.to_llvm_ptr(fx.inttoptr(ptr_ty, fx.Int64(base + off)))


def _lds_ldf(base, off):
    return fx.Float32(llvm.LoadOp(T.f32, _lds(base, off)).res)


def _umax(a, b):
    return (fx.Uint32(a) > fx.Uint32(b)).select(a, b)


def _e8m0(amax_bits):
    """Biased e8m0 exponent of the reference's MXFP4 scale for an |amax| bit pattern."""
    am = amax_bits.bitcast(fx.Float32)
    am = (am > fx.Float32(1e-10)).select(am, fx.Float32(1e-10))
    bits = am.bitcast(fx.Int32)
    return ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))


def _pack_fp4(vals, scale):
    """Eight floats to one dword of fp4 (element j in nibble j)."""
    q = fx.Int32(0)
    for j in range_constexpr(len(vals) // 2):
        q = fx.Int32(
            rocdl.cvt_scalef32_pk_fp4_f32(
                T.i32, _raw(q), _raw(vals[2 * j]), _raw(vals[2 * j + 1]), _raw(scale), j
            )
        )
    return q


def _bf16_bits(x):
    return fx.Int32(fx.BFloat16(x).bitcast(fx.Uint16))


def _quant8(v):
    """Eight bf16 (one i32x4 of packed pairs; 4 consecutive lanes per 32-value group) to
    (fp4 dword, e8m0 exponent of the group)."""
    v2i16 = ir.VectorType.get([2], ir.IntegerType.get_signless(16))
    m = None
    for k in range_constexpr(4):
        a = llvm.BitcastOp(v2i16, _raw(v[k] & 0x7FFF7FFF)).result
        m = a if m is None else arith.maxui(m, a)
    m = fx.Int32(llvm.BitcastOp(T.i32, m).result)
    peak = _umax(m << 16, m & fx.Int32(-65536))
    # quad_perm [1,0,3,2] and [2,3,0,1]
    for ctrl in (0xB1, 0x4E):
        peak = _umax(peak, fx.Int32(rocdl.update_dpp(T.i32, _raw(peak), _raw(peak), ctrl, 0xF, 0xF, True)))
    ex = _e8m0(peak)
    scale = (ex << 23).bitcast(fx.Float32)
    v2bf16 = ir.VectorType.get([2], ir.BF16Type.get())
    q = fx.Int32(0)
    for k in range_constexpr(4):
        q = fx.Int32(
            rocdl.cvt_scalef32_pk_fp4_bf16(
                T.i32, _raw(q), llvm.BitcastOp(v2bf16, _raw(v[k])).result, _raw(scale), k
            )
        )
    return q, ex


def _from_lane(x, src):
    return fx.Int32(rocdl.ds_bpermute(T.i32, _raw(src * 4), _raw(x)))


def _gather_operand(q, ex, first):
    """MFMA operand of the 128-value chunk whose 16 fp4 dwords sit in lanes first .. first + 15
    (lane first + 4 * g + j holds dword j of group g): (i32x4 of group lg, its e8m0)."""
    lane = fx.Int32(gpu.thread_id("x")) % 64
    src = first + (lane // 16) * 4
    av = fx.Vector.from_elements([_from_lane(q, src + j) for j in range_constexpr(4)], fx.Int32)
    return av, _from_lane(ex, src)


def _silu_mul(g, u):
    ep = fx.Float32(rocdl.exp2(T.f32, _raw(g * fx.Float32(-1.4426950408889634))))
    sig = fx.Float32(rocdl.rcp(T.f32, _raw(fx.Float32(1.0) + ep)))
    return g * sig * u


def _silu_mul_bf16(g, u):
    return fx.Float32(fx.BFloat16(_silu_mul(g, u)))


def _store_inter(INTER, route, part, cb, tid, g, u, P):
    """Stage-1 result of one column: silu(g) * u as bf16, or (P > 1) the part's fp32 g and u."""
    if P == 1:
        _st16(_rsrc(INTER), (route * _I + cb * 16 + tid) * 2, _bf16_bits(_silu_mul_bf16(g, u)))
    else:
        o = ((route * P + part) * _N1 + cb * 16 + tid) * 2
        _st16(_rsrc(INTER), o, _bf16_bits(g))
        _st16(_rsrc(INTER), o + _I * 2, _bf16_bits(u))


def _load_inter(INTER, route, lane, P):
    """This lane's 8 consecutive intermediate values: one i32x4 of bf16 pairs, or (P > 1) per part the
    fp32 gate and up partial sums (4 i32x4: gate lo, gate hi, up lo, up hi)."""
    rs = _rsrc(INTER)
    if P == 1:
        return _ld4(rs, route * (_I * 2) + lane * 16)
    return [
        [_ld4(rs, ((route * P + p) * _N1 + gu * _I + lane * 8) * 2) for gu in range_constexpr(2)]
        for p in range_constexpr(P)
    ]


def _bf16_half(w, hi):
    return ((w & fx.Int32(-65536)) if hi else (w << 16)).bitcast(fx.Float32)


def _fold_inter(xa, P):
    """The parts added in part order, silu(gate) * up rounded to bf16 and packed as ``_load_inter``'s P = 1 form."""
    if P == 1:
        return xa
    hb = []
    for j in range_constexpr(8):
        g = None
        u = None
        for p in range_constexpr(P):
            gp = _bf16_half(xa[p][0][j // 2], j % 2)
            up = _bf16_half(xa[p][1][j // 2], j % 2)
            g = gp if g is None else g + gp
            u = up if u is None else u + up
        hb.append(_bf16_bits(_silu_mul_bf16(g, u)))
    return fx.Vector.from_elements([hb[2 * k] | (hb[2 * k + 1] << 16) for k in range_constexpr(4)], fx.Int32)


@functools.cache
def _stage1_kernel(W, P=1):
    """Route-direct gate/up GEMM: grid (routes * 32 * P), 64 * W threads; workgroup part p owns the
    K chunks [p * 48 / P, (p + 1) * 48 / P) of 128, wave w NCH of them. With P > 1 the fp32 gate and
    up sums of each part are stored for stage 2 to add."""
    K = _D
    N = _N1
    NCB = _I // 16
    NCH = K // 128 // (W * P)
    RED_BYTES = W * 2 * 16 * 4
    assert NCH * W * P * 128 == K and NCH % 2 == 0 and (K // 128 // P) % 2 == 0

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, RED_BYTES, 16]

    @flyc.kernel(known_block_size=[64 * W, 1, 1])
    def stage1(X: fx.Int64, IDS: fx.Int64, W1: fx.Int64, WS1: fx.Int64, INTER: fx.Int64):
        tid = fx.Int32(gpu.thread_id("x"))
        bid = fx.Int32(gpu.block_id("x"))
        route = bid // (NCB * P)
        cb = (bid // P) % NCB
        part = bid % P
        lane = tid % 64
        wave = _uniform(tid // 64)
        l16 = lane % 16
        lg = lane // 16
        tok = route // _TOPK
        x = _rsrc(X)
        k0 = part * (K // 128 // P) + wave * NCH
        # The activations do not depend on the expert: issue them ahead of the topk_ids round trip.
        NLD = (NCH * 16 + 63) // 64
        xa = [
            _ld4(
                x,
                tok * (K * 2)
                + k0 * 256
                + (j * 64 + (lane % (NCH * 16 - j * 64 if j * 64 + 64 > NCH * 16 else 64))) * 16,
            )
            for j in range_constexpr(NLD)
        ]
        e = _sload(IDS, route)
        w = _rsrc(W1)
        ws = _rsrc(WS1)
        cols = [cb * 16, _I + cb * 16]
        # Scales ahead of weights (vmcnt retires in order), all loads issued before any use.
        bs_raw = [
            _ld1(ws, e * (N * K // 32) + (n >> 5) * K + lg * 64 + l16 * 4 + ((k0 >> 1) + p) * 256)
            for p in range_constexpr(NCH // 2)
            for n in cols
        ]
        bv = [
            _ld4(w, e * (N * K // 2) + (n >> 4) * (K * 8) + (k0 + i) * 1024 + lane * 16)
            for i in range_constexpr(NCH)
            for n in cols
        ]
        rocdl.sched_barrier(0)
        xq = [_quant8(v) for v in xa]
        shift = (cb & 1) * 8
        bs = [b >> shift for b in bs_raw]
        accs = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range_constexpr(2)]
        for i in range_constexpr(NCH):
            q, ex = xq[(i * 16) // 64]
            av, ax = _gather_operand(q, ex, (i * 16) % 64)
            for t in range_constexpr(2):
                accs[t] = fx.Vector(
                    rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                        T.f32x4, [bv[i * 2 + t], av, accs[t], 4, 4, (i & 1) * 2, bs[(i >> 1) * 2 + t], 0, ax]
                    )
                )
        lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
        if l16 == 0:
            for t in range_constexpr(2):
                llvm.StoreOp(_raw(accs[t]), _lds(lb, ((wave * 2 + t) * 16 + lg * 4) * 4), alignment=16)
        gpu.barrier()
        if tid < 16:
            g = _lds_ldf(lb, tid * 4)
            u = _lds_ldf(lb, (16 + tid) * 4)
            for wv in range_constexpr(1, W):
                g = g + _lds_ldf(lb, ((wv * 2) * 16 + tid) * 4)
                u = u + _lds_ldf(lb, ((wv * 2 + 1) * 16 + tid) * 4)
            _store_inter(INTER, route, part, cb, tid, g, u, P)

    return stage1


@functools.cache
def _stage2_kernel(TN, P=1):
    """Down GEMM and route sum: grid (tokens * 384 / TN), 9 waves, wave r = route slot r; each
    workgroup owns TN adjacent 16-column tiles (one shared scale dword covers 32 columns)."""
    K = _I
    N = _D
    NCB = N // (16 * TN)
    C = 16 * TN

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, _TOPK * C * 4, 16]

    @flyc.kernel(known_block_size=[64 * _TOPK, 1, 1])
    def stage2(INTER: fx.Int64, IDS: fx.Int64, RW: fx.Int64, W2: fx.Int64, WS2: fx.Int64, OUT: fx.Int64):
        tid = fx.Int32(gpu.thread_id("x"))
        bid = fx.Int32(gpu.block_id("x"))
        tok = bid // NCB
        cb = bid % NCB
        lane = tid % 64
        wave = _uniform(tid // 64)
        route = tok * _TOPK + wave
        l16 = lane % 16
        lg = lane // 16
        # Expert-independent loads first: this route's intermediate row and its routing weight.
        xa = _load_inter(INTER, route, lane, P)
        wt = _sload(RW, route).bitcast(fx.Float32)
        e = _sload(IDS, route)
        w = _rsrc(W2)
        ws = _rsrc(WS2)
        n = cb * C
        NS = (TN + 1) // 2
        bs_raw = [
            _ld1(ws, e * (N * K // 32) + ((n >> 5) + h) * K + lg * 64 + l16 * 4 + p * 256)
            for h in range_constexpr(NS)
            for p in range_constexpr(2)
        ]
        bv = [
            _ld4(w, e * (N * K // 2) + ((n >> 4) + t) * (K * 8) + kk * 1024 + lane * 16)
            for t in range_constexpr(TN)
            for kk in range_constexpr(4)
        ]
        rocdl.sched_barrier(0)
        xq, xe = _quant8(_fold_inter(xa, P))
        accs = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range_constexpr(TN)]
        for t in range_constexpr(TN):
            shift = ((cb & 1) * 8) if TN == 1 else (8 * (t & 1))
            bs = [b >> shift for b in bs_raw[(t >> 1) * 2 : (t >> 1) * 2 + 2]]
            for kk in range_constexpr(4):
                av, ax = _gather_operand(xq, xe, kk * 16)
                accs[t] = fx.Vector(
                    rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                        T.f32x4, [bv[t * 4 + kk], av, accs[t], 4, 4, (kk & 1) * 2, bs[kk >> 1], 0, ax]
                    )
                )
        lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
        if l16 == 0:
            for t in range_constexpr(TN):
                ov = fx.Vector.from_elements([accs[t][k] * wt for k in range_constexpr(4)], fx.Float32)
                llvm.StoreOp(_raw(ov), _lds(lb, (wave * C + t * 16 + lg * 4) * 4), alignment=16)
        gpu.barrier()
        if tid < C:
            s = _lds_ldf(lb, tid * 4)
            for r in range_constexpr(1, _TOPK):
                s = s + _lds_ldf(lb, (r * C + tid) * 4)
            _st16(_rsrc(OUT), (tok * N + n + tid) * 2, _bf16_bits(s))

    return stage2


# Token counts served by the two-launch route-direct path: (stage-1 waves per workgroup, stage-2
# 16-column tiles per workgroup, stage-1 K parts).
_DECODE = {1: (4, 2, 3), 2: (4, 4, 2), 4: (6, 2, 2)}


@functools.cache
def _plan(n_tokens):
    cfg = _DECODE.get(n_tokens)
    if cfg is None:
        return None
    W, TN, P = cfg
    s1 = _stage1_kernel(W, P)
    s2 = _stage2_kernel(TN, P)
    routes = n_tokens * _TOPK
    g1 = routes * (_I // 16) * P
    g2 = n_tokens * (_D // (16 * TN))

    @flyc.jit
    def launch(
        X: fx.Int64,
        IDS: fx.Int64,
        W1: fx.Int64,
        WS1: fx.Int64,
        W2: fx.Int64,
        WS2: fx.Int64,
        RW: fx.Int64,
        OUT: fx.Int64,
        INTER: fx.Int64,
        stream: fx.Stream,
    ):
        s1(X, IDS, W1, WS1, INTER).launch(grid=(g1, 1, 1), block=(64 * W, 1, 1), stream=stream)
        s2(INTER, IDS, RW, W2, WS2, OUT).launch(grid=(g2, 1, 1), block=(64 * _TOPK, 1, 1), stream=stream)

    # Kernel arguments arrive preloaded in SGPRs: the first loads need no kernarg s_load round trip.
    launch.compile_hints = {
        "llvm_options": {"amdgpu-kernarg-preload": True, "amdgpu-kernarg-preload-count": 16}
    }
    return launch


def _lds_add(lb, idx, val):
    """LDS atomic add of ``val`` to the i32 at index ``idx``; returns the old value."""
    return fx.Int32(
        llvm.AtomicRMWOp(
            llvm.AtomicBinOp.add,
            _lds(lb, fx.Int32(idx) * 4),
            _raw(fx.Int32(val)),
            llvm.AtomicOrdering.monotonic,
            syncscope="workgroup",
            alignment=4,
        ).result
    )


def _lds_ldi(lb, idx):
    return fx.Int32(llvm.LoadOp(T.i32, _lds(lb, fx.Int32(idx) * 4)).res)


def _lds_sti(lb, idx, v):
    llvm.StoreOp(_raw(fx.Int32(v)), _lds(lb, fx.Int32(idx) * 4), alignment=4)


_NE = 257
_SCR = _D // 32  # e8m0 scales per activation row
_RT = 512  # routing threads per workgroup
_AUX_ES = 2  # routing AUX: the split stage 1's valid-row words, then from this word the experts' row ranges


@functools.cache
def _route_kernel(n, bm, C, Z, Q=0, GS=0, TS=0, ES=0):
    """Routing sort in one launch: G = n / C workgroups place their tokens' routes in block-padded expert ranges, Z more
    zero ``out``, Q more quantize the activations in token order (scales in strips of GS K-step pairs if GS > 0); AUX
    gets the split stage 1's valid-row words (TS > 0) and, from word ES on, each expert's row range (ES > 0)."""
    G = n // C
    NV = n * _TOPK // 4
    NT = _RT
    R = C * _TOPK
    NOUT = n * _D * 2 // 16
    SENT = (_TOPK << 24) | n
    assert n % C == 0 and (n * _TOPK) % 4 == 0 and R <= NT and n // bm + 1 <= NT
    HIST, BEF, BASE, SCAN, RNK = 0, 512, 1024, 1536, 1792
    RANK = ES > 0 and n in _ES_RANK
    NQ = (_NE + G - 1) // G  # experts per routing workgroup
    NU = n * _D // 8  # 8-value units of the activations
    QIT = (NU + Q * NT - 1) // (Q * NT) if Q else 0
    QB = 8  # units in flight per thread

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, (RNK + NQ) * 4, 16]

    @flyc.kernel(known_block_size=[NT, 1, 1])
    def route(
        IDS: fx.Int64,
        TW: fx.Int64,
        SID: fx.Int64,
        SW: fx.Int64,
        SEID: fx.Int64,
        NVI: fx.Int64,
        OUT: fx.Int64,
        X: fx.Int64,
        QO: fx.Int64,
        QS: fx.Int64,
        AUX: fx.Int64,
    ):
        tid = fx.Int32(gpu.thread_id("x"))
        bid = fx.Int32(gpu.block_id("x"))
        lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
        if const_expr(Q > 0):
            if bid >= G + Z:
                xr = _rsrc(X)
                qo = _rsrc(QO)
                qs = _rsrc(QS)
                for i0 in range_constexpr(0, QIT, QB):
                    us = [
                        (it * Q + (bid - (G + Z))) * NT + tid for it in range_constexpr(i0, min(i0 + QB, QIT))
                    ]
                    xs = [
                        _ld4(xr, (u if (i0 + k + 1) * Q * NT <= NU else (u < NU).select(u, fx.Int32(0))) * 16)
                        for k, u in enumerate(us)
                    ]
                    for k in range_constexpr(len(us)):
                        q, ex = _quant8(xs[k])
                        if us[k] < NU:
                            _st(qo, us[k] * 4, q)
                            if (tid & 3) == 0:
                                g = us[k] // 4
                                if const_expr(GS):
                                    # Per strip, for each c < 4 the pairs (8 y + c, 8 y + c + 4) of GS consecutive y.
                                    gl = g % _SCR
                                    g = (
                                        g
                                        - gl
                                        + (gl // (8 * GS)) * (8 * GS)
                                        + (gl % 4) * (2 * GS)
                                        + ((gl // 8) % GS) * 2
                                        + (gl % 8) // 4
                                    )
                                _st(qs, g, arith.trunci(ir.IntegerType.get_signless(8), _raw(ex)))
        if bid >= G:
            o = _rsrc(OUT)
            zero = fx.Vector.filled(4, 0, fx.Int32)
            for it in range_constexpr((NOUT + Z * NT - 1) // (Z * NT) if Z else 0):
                v = (it * Z + (bid - G)) * NT + tid
                if v < NOUT:
                    _st(o, v * 16, zero)
        if bid < G:
            ids = _rsrc(IDS)
            lim = bid * (C * _TOPK)
            _lds_sti(lb, HIST + tid, 0)
            _lds_sti(lb, BEF + tid, 0)
            if const_expr(RANK):
                if tid < NQ:
                    _lds_sti(lb, RNK + tid, 0)
            xs = [
                _ld4(
                    ids,
                    (
                        (it * NT + tid)
                        if (it + 1) * NT <= NV
                        else ((it * NT + tid) < NV).select(it * NT + tid, fx.Int32(0))
                    )
                    * 16,
                )
                for it in range_constexpr((NV + NT - 1) // NT)
            ]
            gpu.barrier()
            for it in range_constexpr((NV + NT - 1) // NT):
                v = it * NT + tid
                if v < NV:
                    for j in range_constexpr(4):
                        _lds_add(lb, HIST + xs[it][j], 1)
                        if v * 4 + j < lim:
                            _lds_add(lb, BEF + xs[it][j], 1)
            gpu.barrier()
            i = tid & 255
            a = ((_lds_ldi(lb, HIST + 2 * i) + (bm - 1)) // bm) * bm
            b = ((_lds_ldi(lb, HIST + 2 * i + 1) + (bm - 1)) // bm) * bm
            s = a + b
            if tid < 256:
                _lds_sti(lb, SCAN + i, s)
            if const_expr(RANK):
                # Rank of each of this workgroup's experts by descending route count (ties by expert id): the count
                # of experts before it, summed by wave ballots.
                hv = _lds_ldi(lb, HIST + (tid < _NE).select(tid, fx.Int32(0)))
                for q in range_constexpr(NQ):
                    e = bid + q * G
                    ce = _lds_ldi(lb, HIST + (e < _NE).select(e, fx.Int32(0)))
                    fl = (tid < _NE) & ((hv > ce) | ((hv == ce) & (tid < e)))
                    bal = rocdl.ballot(T.i64, _raw(fl))
                    nbal = fx.Int32(arith.trunci(T.i32, llvm.intr_ctpop(_raw(bal))))
                    if (tid & 63) == 0:
                        _lds_add(lb, RNK + q, nbal)
            gpu.barrier()
            acc = s
            for d in (1, 2, 4, 8, 16, 32, 64, 128):
                other = _lds_ldi(lb, SCAN + (i >= d).select(i - d, fx.Int32(0)))
                acc = acc + (i >= d).select(other, fx.Int32(0))
                gpu.barrier()
                if tid < 256:
                    _lds_sti(lb, SCAN + i, acc)
                gpu.barrier()
            if tid < 256:
                _lds_sti(lb, BASE + 2 * i, acc - s)
                _lds_sti(lb, BASE + 2 * i + 1, acc - b)
            gpu.barrier()
            _lds_sti(lb, BEF + tid, _lds_ldi(lb, BEF + tid) + _lds_ldi(lb, BASE + tid))
            gpu.barrier()
            sid = _rsrc(SID)
            sw = _rsrc(SW)
            if tid < R:
                r = lim + tid
                e = _ld1(ids, r * 4)
                wt = _ld1(_rsrc(TW), r * 4)
                pos = _lds_add(lb, BEF + e, 1)
                _st(sid, pos * 4, ((r % _TOPK) << 24) | (r // _TOPK))
                _st(sw, pos * 4, wt)
            seid = _rsrc(SEID)
            for q in range_constexpr(NQ):
                e = bid + q * G
                if e < _NE:
                    base = _lds_ldi(lb, BASE + e)
                    cnt = _lds_ldi(lb, HIST + e)
                    nb = (cnt + (bm - 1)) // bm
                    if tid < nb * bm - cnt:
                        _st(sid, (base + cnt + tid) * 4, fx.Int32(SENT))
                        _st(sw, (base + cnt + tid) * 4, fx.Int32(0))
                    if tid < nb:
                        _st(seid, (base // bm + tid) * 4, e)
                    if const_expr(ES > 0):
                        if tid == 0:
                            rk = e
                            if const_expr(RANK):
                                rk = _lds_ldi(lb, RNK + q)
                            _st(_rsrc(AUX), (ES + 4 * rk) * 4, base)
                            _st(_rsrc(AUX), (ES + 4 * rk + 1) * 4, cnt)
                            _st(_rsrc(AUX), (ES + 4 * rk + 2) * 4, e)
            if bid == 0:
                if tid == 0:
                    nv = _rsrc(NVI)
                    _st(nv, 0, _lds_ldi(lb, SCAN + 255))
                    _st(nv, 4, fx.Int32(n))
                    if const_expr(TS > 0):
                        nvv = _lds_ldi(lb, SCAN + 255)
                        head = (nvv < TS * bm).select(nvv, fx.Int32(TS * bm))
                        ax = _rsrc(AUX)
                        _st(ax, 0, nvv - head)
                        _st(ax, 4, fx.Int32(n))

    @flyc.jit
    def launch(
        IDS: fx.Int64,
        TW: fx.Int64,
        SID: fx.Int64,
        SW: fx.Int64,
        SEID: fx.Int64,
        NVI: fx.Int64,
        OUT: fx.Int64,
        X: fx.Int64,
        QO: fx.Int64,
        QS: fx.Int64,
        AUX: fx.Int64,
        stream: fx.Stream,
    ):
        route(IDS, TW, SID, SW, SEID, NVI, OUT, X, QO, QS, AUX).launch(
            grid=(G + Z + Q, 1, 1), block=(NT, 1, 1), stream=stream
        )

    return launch


# Token counts whose expert-stationary stage 2 takes the experts in descending route-count order, so that each round
# hands every workgroup experts of about the same count.
_ES_RANK = frozenset({2048, 4096})


# Token counts whose routing sort (and, for an atomic stage 2, the zeroing of ``out``) is ``_route_kernel``'s one
# launch: (tokens per routing workgroup, zeroing workgroups).
_ROUTE = {256: (2, 128), 512: (4, 128), 1024: (8, 128), 2048: (16, 128), 4096: (32, 128)}


@functools.cache
def _head_resort_kernel(n, ntiles, hr, GS, BM):
    """The first sort blocks' stage 1 fused with the activation-scale re-sort: workgroups below NH each take 16 sorted
    rows of [0, hr) by 32 output columns, reading the token-order MXFP4 activations (scales in ``_route_kernel``'s GS
    order if GS > 0) through each row's token id; the others re-sort ntiles scale tiles into aiter's sorted layout."""
    K = _D
    N = _N1
    NW = 8  # waves, each owning KS K-steps
    KS = K // 128 // NW
    NH = (hr // 16) * (_I // 32)
    NI = 3  # re-sort: scale-column groups per thread
    TPT = 16 * (_SCR // 8 // NI)  # re-sort: threads per 32-row tile
    TPW = 64 * NW // TPT
    NR = (ntiles + TPW - 1) // TPW
    RED = NW // 2 * 4 * 64 * 16

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, RED, 16]

    @flyc.kernel(known_block_size=[64 * NW, 1, 1])
    def head(
        A: fx.Int64,
        AS: fx.Int64,
        W1: fx.Int64,
        WS1: fx.Int64,
        SID: fx.Int64,
        SEID: fx.Int64,
        NVI: fx.Int64,
        A2: fx.Int64,
        OSC: fx.Int64,
        OS: fx.Int64,
    ):
        tid = fx.Int32(gpu.thread_id("x"))
        bid = fx.Int32(gpu.block_id("x"))
        sid = _rsrc(SID)
        qs = _rsrc(AS)
        if bid >= NH:
            # Tile dword (y, c, r) packs scale columns 8 y + c and 8 y + c + 4 of rows r and r + 16.
            tile = (bid - NH) * TPW + tid // TPT
            u = tid % TPT
            r = u % 16
            yg = u // 16
            tc = (tile < ntiles).select(tile, fx.Int32(0))
            fs = [_ld1(sid, (tc * 32 + r + 16 * h) * 4) for h in range_constexpr(2)]
            nv = _sload(NVI, 0)
            words = []
            oks = []
            for h in range_constexpr(2):
                f = fs[h]
                t = f & 0xFFFFFF
                ok = (t < n) & ((f >> 24) < _TOPK)
                t = ok.select(t, fx.Int32(0))
                words.append(
                    [
                        fx.Vector(
                            rocdl.raw_ptr_buffer_load(
                                T.i32x2, qs, fx.Int32(t * _SCR + (yg * NI + i) * 8), fx.Int32(0), 0
                            )
                        )
                        for i in range_constexpr(NI)
                    ]
                )
                oks.append(ok & (tile * 32 + r + 16 * h < nv))
            o = _rsrc(OS)
            if (tile * 32 < nv) & (tile < ntiles):
                for i in range_constexpr(NI):
                    for c in range_constexpr(4):
                        bs = []
                        for half in range_constexpr(2):
                            for h in range_constexpr(2):
                                bs.append(oks[h].select((words[h][i][half] >> (8 * c)) & 255, fx.Int32(0)))
                        v = bs[0] | (bs[1] << 8) | (bs[2] << 16) | (bs[3] << 24)
                        _st(o, tile * (32 * _SCR) + (yg * NI + i) * 256 + c * 64 + r * 4, v)
        else:
            lane = tid % 64
            wave = _uniform(tid // 64)
            l16 = lane % 16
            lg = lane // 16
            rg = bid // (_I // 32)
            cp = bid % (_I // 32)
            a = _rsrc(A)
            # Row ids, then the activations (need the row ids), then the expert and w1.
            f = _ld1(sid, (rg * 16 + l16) * 4)
            k0 = wave * KS
            t = f & 0xFFFFFF
            tok = ((t < n) & ((f >> 24) < _TOPK)).select(t, fx.Int32(0))
            av = [_ld4(a, tok * (K // 2) + (k0 + k) * 64 + lg * 16) for k in range_constexpr(KS)]
            if const_expr(GS):

                def soff(kk):
                    y = kk // 2
                    return (y // GS) * (8 * GS) + lg * (2 * GS) + (y % GS) * 2 + (kk & 1)

                ax = [
                    _ld1(qs, tok * _SCR + (soff(k0 + k) & -4)) >> ((soff(k0 + k) & 3) * 8)
                    for k in range_constexpr(KS)
                ]
            else:
                ax = [_ld1(qs, tok * _SCR + (k0 + k) * 4) >> (lg * 8) for k in range_constexpr(KS)]
            e = _sload(SEID, (rg * 16) // BM)
            w = _rsrc(W1)
            ws = _rsrc(WS1)
            cols = [gu * _I + (2 * cp + cb) * 16 for cb in range_constexpr(2) for gu in range_constexpr(2)]
            bsr = [
                [
                    _ld1(ws, e * (N * K // 32) + (nn >> 5) * K + lg * 64 + l16 * 4 + ((k0 + k) >> 1) * 256)
                    >> (((k0 + k) & 1) * 16 + ((nn >> 4) & 1) * 8)
                    for k in range_constexpr(KS)
                ]
                for nn in cols
            ]
            bv = [
                [
                    _ld4(w, e * (N * K // 2) + (nn >> 4) * (K * 8) + (k0 + k) * 1024 + lane * 16)
                    for k in range_constexpr(KS)
                ]
                for nn in cols
            ]
            rocdl.sched_barrier(0)
            accs = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range_constexpr(4)]
            for k in range_constexpr(KS):
                for j in range_constexpr(4):
                    accs[j] = fx.Vector(
                        rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                            T.f32x4, [bv[j][k], av[k], accs[j], 4, 4, 0, bsr[j][k], 0, ax[k]]
                        )
                    )
            lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
            # Waves 4..7 hand their sums to waves 0..3, which add them and leave the four pair sums in LDS.
            slot = wave % (NW // 2)
            if wave >= NW // 2:
                for j in range_constexpr(4):
                    llvm.StoreOp(_raw(accs[j]), _lds(lb, ((slot * 4 + j) * 64 + lane) * 16), alignment=16)
            gpu.barrier()
            if wave < NW // 2:
                for j in range_constexpr(4):
                    ad = _lds(lb, ((slot * 4 + j) * 64 + lane) * 16)
                    hv = fx.Vector(llvm.LoadOp(T.f32x4, ad, alignment=16).res)
                    sv = fx.Vector.from_elements([accs[j][i] + hv[i] for i in range_constexpr(4)], fx.Float32)
                    llvm.StoreOp(_raw(sv), ad, alignment=16)
            gpu.barrier()
            if tid < 256:
                rl = tid // 16
                jj = tid % 16
                cb = jj // 8
                c16 = (jj % 8) * 2
                ln = (c16 // 4) * 16 + rl
                ii = c16 % 4
                vs = []
                for x in range_constexpr(2):
                    gs = None
                    us = None
                    for wv in range_constexpr(NW // 2):
                        gv = _lds_ldf(lb, ((wv * 4 + cb * 2) * 64 + ln) * 16 + (ii + x) * 4)
                        uv = _lds_ldf(lb, ((wv * 4 + cb * 2 + 1) * 64 + ln) * 16 + (ii + x) * 4)
                        gs = gv if gs is None else gs + gv
                        us = uv if us is None else us + uv
                    vs.append(_silu_mul(gs, us))
                fm = fx.Float32(
                    arith.maximumf(
                        _raw(fx.Float32(llvm.intr_fabs(_raw(vs[0])))),
                        _raw(fx.Float32(llvm.intr_fabs(_raw(vs[1])))),
                    )
                )
                for d in (1, 2, 4, 8):
                    other = _from_lane(fm.bitcast(fx.Int32), lane ^ d).bitcast(fx.Float32)
                    fm = fx.Float32(arith.maximumf(_raw(fm), _raw(other)))
                # aiter's stage-1 scale: e8m0 = max(exponent of amax rounded, minus 2, 0).
                mb = fm.bitcast(fx.Int32)
                ex = (((mb + 0x400000) & fx.Int32(-8388608)) >> 23) - 2
                ex = (ex < 0).select(fx.Int32(0), ex)
                scale = (ex << 23).bitcast(fx.Float32)
                q = fx.Int32(
                    rocdl.cvt_scalef32_pk_fp4_f32(
                        T.i32, _raw(fx.Int32(0)), _raw(vs[0]), _raw(vs[1]), _raw(scale), 0
                    )
                )
                row = rg * 16 + rl
                i8 = ir.IntegerType.get_signless(8)
                _st(_rsrc(A2), row * (_I // 2) + cp * 16 + jj, arith.trunci(i8, _raw(q)))
                if jj == 0:
                    _st(
                        _rsrc(OSC),
                        (row // 32) * (32 * (_I // 32))
                        + (cp // 8) * 256
                        + (cp % 4) * 64
                        + (row % 16) * 4
                        + (row % 32) // 16
                        + 2 * ((cp % 8) // 4),
                        arith.trunci(i8, _raw(ex)),
                    )

    @flyc.jit
    def launch(
        A: fx.Int64,
        AS: fx.Int64,
        W1: fx.Int64,
        WS1: fx.Int64,
        SID: fx.Int64,
        SEID: fx.Int64,
        NVI: fx.Int64,
        A2: fx.Int64,
        OSC: fx.Int64,
        OS: fx.Int64,
        stream: fx.Stream,
    ):
        head(A, AS, W1, WS1, SID, SEID, NVI, A2, OSC, OS).launch(
            grid=(NH + NR, 1, 1), block=(64 * NW, 1, 1), stream=stream
        )

    launch.compile_hints = {
        "llvm_options": {"amdgpu-kernarg-preload": True, "amdgpu-kernarg-preload-count": 16}
    }
    return launch


