def _mfma_guard_edit(indent, single):
    """The gate/up MFMA pair of one 16-row sub-block at ``indent`` (B-major phase: 28, tail tile: 48), and the same
    pair built only for sub-blocks below the body's ``_MEFF``."""
    lines = [
        "acc_idx = mi_idx * num_acc_n + ni_idx",
        "gate_list[acc_idx] = mixed_b_mfma(",
        "    a128",
        "    gb128",
        "    gate_list[acc_idx]",
        "    ikxdl * pack_M + imxdl",
        "    a_scale_val",
        "    ikxdl * pack_N + inxdl",
        "    gate_bs_val",
        ")",
        f"if const_expr(not {single}):",
        "    up_list[acc_idx] = mixed_b_mfma(",
        "        a128",
        "        ub128",
        "        up_list[acc_idx]",
        "        ikxdl * pack_M + imxdl",
        "        a_scale_val",
        "        ikxdl * pack_N + inxdl",
        "        up_bs_val",
        "    )",
    ]
    sp = " " * indent
    text = [
        sp + ln + ("," if ln.startswith("    ") and not ln.rstrip().endswith(("(", ")")) else "") + "\n"
        for ln in lines
    ]
    old = "".join(text)
    new = text[0] + f"{sp}if const_expr(mi_idx < _MEFF):\n" + "".join("    " + t for t in text[1:])
    return old, new


