def _patched_module(base, edits, suffix):
    """A copy of module ``base`` with each (old, new) source edit applied once, registered beside it as
    ``<base>_aklr_<suffix>``."""
    import importlib.util
    import inspect
    import linecache
    import sys

    src = inspect.getsource(base)
    for old, new in edits:
        if old not in src:
            raise RuntimeError(f"aiter source of {base.__name__} changed")
        src = src.replace(old, new, 1)
    name = f"{base.__name__}_aklr_{suffix}"
    fname = f"{base.__file__[:-3]}_aklr_{suffix}.py"
    linecache.cache[fname] = (len(src), None, src.splitlines(True), fname)
    spec = importlib.util.spec_from_loader(name, loader=None, origin=fname)
    mod = importlib.util.module_from_spec(spec)
    mod.__file__ = fname
    mod.__package__ = base.__package__
    sys.modules[name] = mod
    exec(compile(src, fname, "exec"), mod.__dict__)
    return mod


