_FP4_PITCH = _D // 2 + _D // 32  # MXFP4 route row: e2m1 pairs, then one e8m0 per 32 columns


_ES_TW = 4  # expert-stationary stage 2: 16-column tiles per wave
_ES_NB = _D // (64 * _ES_TW)  # column blocks per expert
_ES_GRID = 512  # persistent expert-stationary stage 2: workgroups


def _swap_max(m, op):
    """Unsigned max of ``m`` with its value in the partner row (permlane16_swap: lane ^ 16; permlane32_swap: lane ^ 32),
    without an LDS round trip."""
    r = op(ir.Type.parse("!llvm.struct<(i32, i32)>"), _raw(m), _raw(m), False, False)
    return _umax(
        fx.Int32(llvm.ExtractValueOp(T.i32, r, [0]).res), fx.Int32(llvm.ExtractValueOp(T.i32, r, [1]).res)
    )


# Expert-stationary stage 2, per token count: (chunks of a panel unrolled ahead of the chunk loop, boundaries of the
# slices of the next panel's w2 loads those chunks issue[, whether chunk 0 issues its slice before staging chunk 1]).
_ES_PEEL = {1024: (2, (0, 20, 20)), 2048: (3, (0, 8, 14, 20)), 4096: (5, (0, 8, 11, 14, 17, 20), True)}


@functools.cache
def _es_stage2_kernel(PEEL, SL, EARLY=False):
    """Persistent expert-stationary down GEMM writing unweighted MXFP4 route rows: a workgroup holds one panel's w2 (an
    expert by _ES_NB-th of the output columns) in registers while the next panel's is in flight, and streams the
    expert's sorted rows 32 at a time through an LDS double buffer, the first PEEL chunks issuing slices SL of that w2."""
    K = _I
    N = _D
    TW = _ES_TW
    NB = _ES_NB
    NWG = _NE * NB
    G = _ES_GRID
    RB = 2 * 16 * TW  # bytes of a route row per workgroup (4 waves of 16 TW columns)
    SB = TW // 2  # scale bytes per wave
    OBUF = 32 * RB + 32 * 4 * SB  # one chunk of output: 32 rows of data then 32 rows of scales
    AROW = K // 2  # bytes of an A row
    ABUF = 32 * AROW + 32 * (K // 32) + 32 * 4  # one chunk of A: 32 rows of data, their scales and row ids
    assert AROW == 256 and 32 * AROW == 2 * 256 * 16 and NWG > G

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, 2 * ABUF + 2 * OBUF, 16]

    @flyc.kernel(known_block_size=[256, 1, 1])
    def es2(
        A: fx.Int64,
        AS: fx.Int64,
        W2: fx.Int64,
        WS2: fx.Int64,
        SID: fx.Int64,
        EINFO: fx.Int64,
        OUT: fx.Int64,
        NREC: fx.Int32,
    ):
        tid = fx.Int32(gpu.thread_id("x"))
        g = fx.Int32(gpu.block_id("x"))
        lane = tid % 64
        wave = _uniform(tid // 64)
        l16 = lane % 16
        lg = lane // 16
        w = _rsrc(W2)
        ws = _rsrc(WS2)
        a = _rsrc(A)
        asr = _rsrc(AS)
        sid = _rsrc(SID)
        ei = _rsrc(EINFO)
        o = _rsrc(OUT, NREC)
        lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
        ob0 = lb + 2 * ABUF
        i8 = ir.IntegerType.get_signless(8)
        orow = tid // 8
        oseg = tid % 8
        # This thread's 16-byte units of a chunk: rows j * 16 + tid / 16, segment tid % 16, stored at segment
        # (tid % 16) ^ (tid / 16) so the MFMA operand reads (16 rows, one segment each) spread over all banks.
        wseg = ((tid % 16) ^ (tid // 16)) * 16

        def clampp(p):
            return (p < NWG).select(p, fx.Int32(NWG - 1))

        def w2_regs(p, e, lo=0, hi=5 * TW):
            """Loads lo .. hi - 1 of the panel's w2 (``e``: its expert): TW scale dwords, then 4 TW 16-byte units."""
            pc = clampp(p)
            n0 = (pc % NB) * (64 * TW) + wave * (16 * TW)
            res = []
            for i in range_constexpr(lo, hi):
                if const_expr(i < TW):
                    h = i // 2
                    q = i % 2
                    res.append(
                        _raw(_ld1(ws, e * (N * K // 32) + ((n0 >> 5) + h) * K + lg * 64 + l16 * 4 + q * 256))
                    )
                else:
                    t = (i - TW) // 4
                    kk = (i - TW) % 4
                    res.append(
                        _raw(
                            rocdl.raw_ptr_buffer_load(
                                T.i32x4,
                                w,
                                fx.Int32(
                                    e * (N * K // 2) + ((n0 >> 4) + t) * (K * 8) + kk * 1024 + lane * 16
                                ),
                                fx.Int32(0),
                                2,
                            )
                        )
                    )
            return res

        def einfo_regs(p):
            r = clampp(p) // NB
            return [_raw(_ld1(ei, r * 16 + 4 * i)) for i in range_constexpr(3)]

        def load_chunk(base, nch, ci):
            cc = (ci < nch).select(ci, nch - 1)
            cc = (cc < 0).select(fx.Int32(0), cc)
            r = base + cc * 32
            d = [_ld4(a, r * AROW + (j * 256 + tid) * 16) for j in range_constexpr(2)]
            sc = _ld1(asr, (r // 32) * K + (tid & 127) * 4)
            f = _ld1(sid, (r + (tid & 31)) * 4)
            return [_raw(d[0]), _raw(d[1]), _raw(sc), _raw(f)]

        def to_lds(regs, buf):
            for j in range_constexpr(2):
                llvm.StoreOp(regs[j], _lds(buf + (j * 16 + tid // 16) * AROW + wseg, 0), alignment=16)
            if tid < 128:
                llvm.StoreOp(regs[2], _lds(buf + 32 * AROW + tid * 4, 0), alignment=4)
            if tid < 32:
                llvm.StoreOp(regs[3], _lds(buf + 32 * AROW + 512 + tid * 4, 0), alignment=4)

        # Prologue: the first panel's w2, row range and first two chunks; the second panel's row range.
        gl = (g % 8) * (G // 8) + g // 8
        ein0 = einfo_regs(gl)
        ein1 = einfo_regs(gl + G)
        w0 = w2_regs(gl, _uniform(fx.Int32(ein0[2])))
        base0 = _uniform(fx.Int32(ein0[0]))
        cnt0 = _uniform(fx.Int32(ein0[1]))
        nch0 = (cnt0 + 31) // 32
        to_lds(load_chunk(base0, nch0, fx.Int32(0)), lb)
        a1 = load_chunk(base0, nch0, fx.Int32(1))
        gpu.barrier()
        npan = (NWG - 1 - gl) // G + 1
        init = w0 + ein1 + a1 + [_raw(base0), _raw(cnt0)]
        for j, ost in range(fx.Int32(0), npan, fx.Int32(1), init=init):
            p = gl + fx.Int32(j) * G
            nb = p % NB
            bs_raw = [fx.Int32(ost[i]) for i in range_constexpr(TW)]
            bv = [fx.Vector(ost[TW + i]) for i in range_constexpr(4 * TW)]
            ein_n = [ost[5 * TW + i] for i in range_constexpr(3)]
            a_1 = [ost[5 * TW + 3 + i] for i in range_constexpr(4)]
            base = fx.Int32(ost[5 * TW + 7])
            cnt = fx.Int32(ost[5 * TW + 8])
            e_n = _uniform(fx.Int32(ein_n[2]))
            nch = (cnt + 31) // 32

            def chunk(ci, ist, ahead, early=False, nch=nch, cnt=cnt, nb=nb, bv=bv, bs_raw=bs_raw):
                """Chunk ci of panel p: chunk ci + 1 (``ist``) to LDS, ``ahead`` (the loads it issues are returned),
                chunk ci's MFMAs, quantization and stores."""
                if const_expr(early):
                    nxt = ahead()
                if ci + 1 < nch:
                    to_lds(list(ist), lb + ((ci + 1) & 1) * ABUF)
                if const_expr(not early):
                    nxt = ahead()
                abuf = lb + (ci & 1) * ABUF
                as_raw = [
                    fx.Int32(
                        llvm.LoadOp(
                            T.i32, _lds(abuf + 32 * AROW + q * 256 + lg * 64 + l16 * 4, 0), alignment=4
                        ).res
                    )
                    for q in range_constexpr(2)
                ]
                fo = fx.Int32(llvm.LoadOp(T.i32, _lds(abuf + 32 * AROW + 512 + orow * 4, 0), alignment=4).res)
                bb = ob0 + (ci & 1) * OBUF

                def mma(rt, accs):
                    rocdl.s_setprio(1)
                    av = [
                        fx.Vector(
                            llvm.LoadOp(
                                T.i32x4,
                                _lds(abuf + (rt * 16 + l16) * AROW + (((kk * 4 + lg) ^ l16) * 16), 0),
                                alignment=16,
                            ).res
                        )
                        for kk in range_constexpr(4)
                    ]
                    for t in range_constexpr(TW):
                        for kk in range_constexpr(4):
                            accs[t][rt] = fx.Vector(
                                rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                                    T.f32x4,
                                    [
                                        bv[t * 4 + kk],
                                        av[kk],
                                        accs[t][rt],
                                        4,
                                        4,
                                        (kk & 1) * 2,
                                        bs_raw[(t >> 1) * 2 + (kk >> 1)] >> (8 * (t & 1)),
                                        (kk & 1) * 2,
                                        as_raw[kk >> 1] >> (8 * rt),
                                    ],
                                )
                            )

                def quant(rt, accs):
                    rocdl.s_setprio(0)
                    row = rt * 16 + l16
                    for b in range_constexpr(TW // 2):
                        vals = [
                            accs[2 * b + h][rt][i] for h in range_constexpr(2) for i in range_constexpr(4)
                        ]
                        # |x| ordered as floats is |x| ordered as bit patterns: abs modifiers on a float max3 tree.
                        fm = None
                        for jj in range_constexpr(8):
                            x = fx.Float32(llvm.intr_fabs(_raw(vals[jj])))
                            fm = x if fm is None else fx.Float32(arith.maximumf(_raw(fm), _raw(x)))
                        m = fm.bitcast(fx.Int32)
                        m = _swap_max(m, rocdl_ods.permlane16_swap)
                        m = _swap_max(m, rocdl_ods.permlane32_swap)
                        ex = ((m >> 23) & 255) - 2
                        ex = (ex < 1).select(fx.Int32(1), ex)
                        ex = (m == 0).select(fx.Int32(0), ex)
                        scale = (m == 0).select(fx.Float32(1.0), (ex << 23).bitcast(fx.Float32))
                        q = _pack_fp4(vals, scale)
                        ob = bb + row * RB + wave * (16 * TW // 2) + 16 * b + 2 * lg
                        llvm.StoreOp(arith.trunci(T.i16, _raw(q)), _lds(ob, 0), alignment=2)
                        llvm.StoreOp(arith.trunci(T.i16, _raw(q >> 16)), _lds(ob + 8, 0), alignment=2)
                        if lg == 0:
                            llvm.StoreOp(
                                arith.trunci(i8, _raw(ex)),
                                _lds(bb + 32 * RB + row * (4 * SB) + wave * SB + b, 0),
                                alignment=1,
                            )

                def half(rt):
                    accs = [
                        [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range_constexpr(2)]
                        for _ in range_constexpr(TW)
                    ]
                    mma(rt, accs)
                    quant(rt, accs)

                # One 16-row half at a time keeps half the accumulators live; halves without rows are skipped.
                if ci * 32 + 16 < cnt:
                    half(0)
                    half(1)
                if (ci * 32 + 16 >= cnt) & (ci < nch):
                    half(0)
                gpu.barrier()
                # Padding rows carry token n_tokens, slot topk: their destination lies past the output's bounds.
                dest = ((fo & 0xFFFFFF) * _TOPK + (fo >> 24)) * _FP4_PITCH
                dest = (ci < nch).select(dest, NREC)
                for hh in range_constexpr(RB // 128):
                    v = fx.Vector(
                        llvm.LoadOp(T.i32x4, _lds(bb + orow * RB + (oseg + 8 * hh) * 16, 0), alignment=16).res
                    )
                    _st(o, dest + nb * RB + (oseg + 8 * hh) * 16, v)
                # Unconditional, so the wait counts stay exact: the lanes past a row's scale dwords aim past the bounds.
                sseg = oseg % (SB)
                sv = fx.Int32(
                    llvm.LoadOp(T.i32, _lds(bb + 32 * RB + orow * (4 * SB) + sseg * 4, 0), alignment=4).res
                )
                _st(o, (oseg < SB).select(dest + _D // 2 + nb * (4 * SB) + sseg * 4, NREC), sv)
                return nxt

            # Chunk 2 ahead of the next panel's w2: the wait for it (chunk 1's iteration) does not wait for that w2 too.
            nxt2 = load_chunk(base, nch, fx.Int32(2))
            base_n = _uniform(fx.Int32(ein_n[0]))
            cnt_n = _uniform(fx.Int32(ein_n[1]))
            nch_n = (cnt_n + 31) // 32
            wn = []
            cur = a_1
            for k in range_constexpr(PEEL):

                def ahead(k=k, base=base, nch=nch, p=p, e_n=e_n, base_n=base_n, nch_n=nch_n):
                    r = []
                    if const_expr(k >= 1):
                        r.append(load_chunk(base, nch, fx.Int32(k + 2)))
                    r.append(w2_regs(p + G, e_n, SL[k], SL[k + 1]))
                    if const_expr(k == PEEL - 1):
                        r.append(einfo_regs(p + 2 * G))
                        r.append(load_chunk(base_n, nch_n, fx.Int32(0)))
                    return r

                r = chunk(fx.Int32(k), cur, ahead, early=EARLY and k == 0)
                if const_expr(k >= 1):
                    cur = r[0]
                    r = r[1:]
                else:
                    cur = nxt2
                wn = wn + r[0]
                if const_expr(k == PEEL - 1):
                    ein_nn = r[1]
                    an0 = r[2]
            for c, ist in range(fx.Int32(PEEL), nch, fx.Int32(1), init=cur):
                ci = fx.Int32(c)
                yield chunk(ci, ist, lambda ci=ci, base=base, nch=nch: load_chunk(base, nch, ci + 2))
            # Every read of both A buffers is behind the loop's last barrier: chunk 0 of the next panel goes to buffer 0.
            to_lds(an0, lb)
            an1 = load_chunk(base_n, nch_n, fx.Int32(1))
            gpu.barrier()
            yield wn + ein_nn + an1 + [_raw(base_n), _raw(cnt_n)]

    @flyc.jit
    def launch(
        A: fx.Int64,
        AS: fx.Int64,
        W2: fx.Int64,
        WS2: fx.Int64,
        SID: fx.Int64,
        EINFO: fx.Int64,
        OUT: fx.Int64,
        NREC: fx.Int32,
        stream: fx.Stream,
    ):
        es2(A, AS, W2, WS2, SID, EINFO, OUT, NREC).launch(grid=(G, 1, 1), block=(256, 1, 1), stream=stream)

    launch.compile_hints = {
        "waves_per_eu": G // 256,
        "llvm_options": {"amdgpu-kernarg-preload": True, "amdgpu-kernarg-preload-count": 16},
    }
    return launch


_RCPT = 16  # reduce: columns per thread (half an e8m0 scale block)


@functools.cache
def _fp4_reduce_kernel(n_tokens):
    """Route reduction of MXFP4 route rows: one workgroup per token, thread t owning columns _RCPT t .. _RCPT (t + 1) - 1;
    the routes are decoded, weighted and added in route order in fp32 and stored as bf16."""
    NT = _D // _RCPT
    NW = _RCPT // 8  # fp4 dwords per route

    @flyc.kernel(known_block_size=[NT, 1, 1])
    def reduce(X: fx.Int64, TW: fx.Int64, OUT: fx.Int64):
        tid = fx.Int32(gpu.thread_id("x"))
        tok = fx.Int32(gpu.block_id("x"))
        x = _rsrc(X)
        rows = [(tok * _TOPK + r) * _FP4_PITCH for r in range_constexpr(_TOPK)]
        data = [
            fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x2, x, fx.Int32(rows[r] + tid * (NW * 4)), fx.Int32(0)))
            for r in range_constexpr(_TOPK)
        ]
        sb = (tid * _RCPT) // 32
        sc = [_ld1(x, rows[r] + _D // 2 + (sb & -4)) for r in range_constexpr(_TOPK)]
        wts = [_sload(TW, tok * _TOPK + r).bitcast(fx.Float32) for r in range_constexpr(_TOPK)]
        rocdl.sched_barrier(0)
        sh = (sb & 3) * 8
        acc = [fx.Float32(0.0)] * _RCPT
        for r in range_constexpr(_TOPK):
            scale = (((sc[r] >> sh) & 255) << 23).bitcast(fx.Float32)
            for j in range_constexpr(NW):
                for s in range_constexpr(4):
                    pr = fx.Vector(rocdl.cvt_scalef32_pk_f32_fp4(T.f32x2, _raw(data[r][j]), _raw(scale), s))
                    for h in range_constexpr(2):
                        i = j * 8 + s * 2 + h
                        acc[i] = acc[i] + pr[h] * wts[r]
        o = _rsrc(OUT)
        for q in range_constexpr(_RCPT // 8):
            v = fx.Vector.from_elements(
                [
                    _bf16_bits(acc[q * 8 + 2 * k]) | (_bf16_bits(acc[q * 8 + 2 * k + 1]) << 16)
                    for k in range_constexpr(4)
                ],
                fx.Int32,
            )
            _st(o, tok * (_D * 2) + tid * (_RCPT * 2) + q * 16, v)

    @flyc.jit
    def launch(X: fx.Int64, TW: fx.Int64, OUT: fx.Int64, stream: fx.Stream):
        reduce(X, TW, OUT).launch(grid=(n_tokens, 1, 1), block=(NT, 1, 1), stream=stream)

    launch.compile_hints = {
        "llvm_options": {"amdgpu-kernarg-preload": True, "amdgpu-kernarg-preload-count": 16}
    }
    return launch


def _stage2_fp4_reduce(
    inter_states,
    w1,
    w2,
    sorted_token_ids,
    sorted_expert_ids,
    num_valid_ids,
    out,
    topk,
    model_dim=0,
    w2_scale=None,
    a2_scale=None,
    sorted_weights=None,
    bias2=None,
    topk_weights=None,
    es=None,
    **_kwargs,
):
    """aiter's reduce stage 2 replaced by ``_es_stage2_kernel`` (route partials in MXFP4, e8m0 per 32) and
    ``_fp4_reduce_kernel``, which applies the routing weights and writes ``out``."""
    if topk_weights is None or sorted_weights is None or bias2 is not None or topk != _TOPK:
        raise ValueError("fp4 route partials need sorted_weights and topk_weights, no bias")
    token_num, mdim = out.shape
    assert mdim == _D and model_dim == _D
    target = torch.empty((token_num * topk, _FP4_PITCH), dtype=torch.uint8, device=out.device)
    stream = torch.cuda.current_stream(out.device).cuda_stream
    _es_stage2_kernel(*_ES_PEEL[token_num])(
        inter_states.data_ptr(),
        a2_scale.data_ptr(),
        w2.data_ptr(),
        w2_scale.data_ptr(),
        sorted_token_ids.data_ptr(),
        es.data_ptr(),
        target.data_ptr(),
        target.numel(),
        stream,
    )
    _fp4_reduce_kernel(token_num)(target.data_ptr(), topk_weights.data_ptr(), out.data_ptr(), stream)
    return out


@functools.cache
def _compile_s1_vb(gather=0, **kw):
    from aiter.ops.flydsl.moe_common import GateMode

    kw["gate_mode"] = GateMode(kw["gate_mode"])
    return _s1_valid_bound_module(gather).compile_mixed_moe_gemm1_common(**kw)


def _stage1_valid_bound(
    hidden_states,
    w1,
    w2,
    sorted_token_ids,
    sorted_expert_ids,
    num_valid_ids,
    out,
    topk,
    kernelName="",
    activation=None,
    w1_scale=None,
    a1_scale=None,
    sorted_weights=None,
    bias1=None,
    topk_ids=None,
    inter_dim_pad=0,
    model_dim_pad=0,
    out_dtype=None,
    v2_output_layout=False,
    gather=0,
    split=None,
    **_kwargs,
):
    """aiter's FlyDSL stage 1 (silu, no bias) built by ``_s1_valid_bound_module`` (``gather`` > 0: reading token-order
    A scales in chunks of that many K-steps)."""
    from aiter.ops.flydsl.moe_kernels import _flydsl_moe_stage1_impl

    if split is not None:
        return _stage1_split(
            hidden_states,
            w1,
            w2,
            sorted_token_ids,
            sorted_expert_ids,
            out,
            topk,
            kernelName,
            w1_scale,
            a1_scale,
            sorted_weights,
            bias1,
            inter_dim_pad,
            model_dim_pad,
            out_dtype,
            v2_output_layout,
            split,
            gather,
        )
    p = _s1_params(kernelName)
    if bias1 is not None or p is None:
        raise ValueError("valid-bound stage 1 takes no bias")
    if out_dtype is not None:
        p = {**p, "out_dtype": out_dtype}
    return _flydsl_moe_stage1_impl(
        a=hidden_states,
        w1=w1,
        sorted_token_ids=sorted_token_ids,
        sorted_expert_ids=sorted_expert_ids,
        num_valid_ids=num_valid_ids,
        out=out,
        topk=topk,
        tile_m=p["tile_m"],
        tile_n=p["tile_n"],
        tile_k=p["tile_k"],
        a_dtype=p["a_dtype"],
        b_dtype=p["b_dtype"],
        out_dtype=p["out_dtype"],
        act="silu",
        w1_scale=w1_scale,
        a1_scale=a1_scale,
        sorted_weights=sorted_weights,
        use_async_copy=True,
        k_batch=p.get("k_batch", 1),
        waves_per_eu=p.get("waves_per_eu", 3),
        b_nt=p.get("b_nt", 2),
        gate_mode=p.get("gate_mode", "separated"),
        inter_dim_pad=inter_dim_pad,
        model_dim_pad=model_dim_pad,
        topk_ids=topk_ids,
        a_scale_one=p.get("a_scale_one", False),
        xcd_swizzle=p.get("xcd_swizzle", 0),
        k_wave=p.get("k_wave", 1),
        v2_output_layout=v2_output_layout,
        **({"_build_mx_args": _kwargs["_build_mx_args"]} if "_build_mx_args" in _kwargs else {}),
        _compile_kernel=functools.partial(_compile_s1_vb, gather) if gather else _compile_s1_vb,
    )


def _stage1_split(
    hidden_states,
    w1,
    w2,
    sorted_token_ids,
    sorted_expert_ids,
    out,
    topk,
    kernelName,
    w1_scale,
    a1_scale,
    sorted_weights,
    bias1,
    inter_dim_pad,
    model_dim_pad,
    out_dtype,
    v2_output_layout,
    split,
    gather=0,
):
    """Stage 1 as two launches over one sorted output: rows [0, TS sbm) by ``_head_resort_kernel``, the rest by
    ``kernelName`` (valid-row words from ``_route_kernel``'s AUX) through views offset by TS sort blocks (sorted ids,
    block experts, output rows, the 32-row-group-major A and output e8m0 scales)."""
    import aiter
    from aiter.ops.flydsl.moe_kernels import _s1_args_fp4

    aux, ts, tok_scale, nvi, nt, gs = split
    p = _s1_params(kernelName)
    sbm = p["tile_m"]
    if (
        bias1 is not None
        or not v2_output_layout
        or p.get("out_dtype", out_dtype) != "fp4"
        or out is not None
        or a1_scale is None
        or sorted_token_ids.shape[0] < ts * sbm
        or sbm % 32
    ):
        raise ValueError("split stage 1: fp4 sorted output with pre-sorted A scales only")
    dev = sorted_token_ids.device
    rows = max(sorted_token_ids.shape[0], sorted_expert_ids.shape[0] * sbm)
    scols = ((_I // 32) + 7) // 8 * 8
    prow = (rows + 255) // 256 * 256
    a2 = torch.empty((rows, _I // 2), dtype=aiter.dtypes.fp4x2, device=dev)
    oscale = torch.empty(prow * scols, dtype=torch.uint8, device=dev)
    a1s = a1_scale.view(-1)
    hr = ts * sbm  # head rows

    def _args_into(view):
        def build(*args, **kw):
            args = list(args)
            args[9] = view
            return _s1_args_fp4(*args, **kw)

        return build

    common = dict(
        hidden_states=hidden_states,
        w1=w1,
        w2=w2,
        topk=topk,
        w1_scale=w1_scale,
        sorted_weights=sorted_weights,
        inter_dim_pad=inter_dim_pad,
        model_dim_pad=model_dim_pad,
        out_dtype=out_dtype,
        v2_output_layout=True,
        gather=gather,
    )
    assert gs == gather and scols == 16
    _head_resort_kernel(int(tok_scale.shape[0]), nt, hr, gs, sbm)(
        hidden_states.data_ptr(),
        tok_scale.data_ptr(),
        w1.data_ptr(),
        w1_scale.data_ptr(),
        sorted_token_ids.data_ptr(),
        sorted_expert_ids.data_ptr(),
        nvi.data_ptr(),
        a2.data_ptr(),
        oscale.data_ptr(),
        a1s.data_ptr(),
        torch.cuda.current_stream(dev).cuda_stream,
    )
    _stage1_valid_bound(
        sorted_token_ids=sorted_token_ids[hr:],
        sorted_expert_ids=sorted_expert_ids[ts:],
        num_valid_ids=aux[0:2],
        out=a2[hr:],
        kernelName=kernelName,
        a1_scale=a1s if gather else a1s[hr * (_D // 32) :],
        _build_mx_args=_args_into(oscale[hr // 32 * 32 * scols :]),
        **common,
    )
    return a2, oscale.view(aiter.dtypes.fp8_e8m0).view(prow, scols)


def _fp4_transform(md, es):
    """Metadata transform swapping the bf16 reduce stage 2 for ``_stage2_fp4_reduce`` (a new object; the
    cached metadata aiter's own calls read is left untouched)."""
    import dataclasses

    s2 = md.stage2
    return dataclasses.replace(
        md, stage2=functools.partial(_stage2_fp4_reduce, *s2.args, **s2.keywords, es=es)
    )


def _rename(stage, name):
    return functools.partial(stage.func, *stage.args, **{**stage.keywords, "kernelName": name})


def _kernels_transform(override, fp4, md, vb=False, gather=0, split=None, es=None):
    """Metadata transform naming other stage kernels (and the MXFP4 route partials where asked; with ``vb`` stage 1
    is ``_stage1_valid_bound``)."""
    import dataclasses

    if override is not None and override[0] == "aux":
        _, kn1, kn2 = override
        s1, s2 = md.stage1, md.stage2
        md = dataclasses.replace(
            md,
            stage1=functools.partial(s1.func, *s1.args, **{**s1.keywords, "kernelName1": kn1}),
            stage2=functools.partial(s2.func, *s2.args, **{**s2.keywords, "kernelName2": kn2}),
        )
    elif override is not None:
        bm, kn1, kn2 = override
        md = dataclasses.replace(
            md, stage1=_rename(md.stage1, kn1), stage2=_rename(md.stage2, kn2), block_m=bm
        )
    if vb or gather:
        s1 = md.stage1
        md = dataclasses.replace(
            md,
            stage1=functools.partial(
                _stage1_valid_bound,
                *s1.args,
                **{
                    **s1.keywords,
                    "v2_output_layout": bool(md.skip_inter_quant),
                    "gather": gather,
                    **({"split": split} if split is not None else {}),
                },
            ),
        )
    return _fp4_transform(md, es) if fp4 else md


@functools.cache
def _aiter_plan(n_tokens, w1_dtype, shuffled):
    """How aiter's fused_moe would sort and run this token count, mirrored so that its result is
    written straight into the caller's ``out``: (branch, block_m, metadata, q_dtype_a) or None.
    Branch "aux": adaptive aux sort (BM=16) zeroes ``out`` for the atomic stage 2; "atomic": opus
    sort zeroes ``out`` for the atomic stage 2; "reduce": stage 2's route reduction writes ``out``."""
    import aiter
    from aiter import ActivationType, QuantType
    from aiter import fused_moe as fm
    from aiter.fused_moe import GateMode

    q_dtype_a = aiter.dtypes.fp4x2
    md = fm.get_2stage_cfgs(
        fm.get_padded_M(n_tokens),
        _D,
        _I,
        257,
        _TOPK,
        torch.bfloat16,
        q_dtype_a,
        w1_dtype,
        QuantType.per_1x32,
        True,
        ActivationType.Silu,
        False,
        0,
        0,
        shuffled,
        GateMode.SEPARATED,
        is_ep=False,
        has_stage2_bias=False,
        opus_weights_shuffled=shuffled,
        config_file=None,
    )
    if md.run_1stage or md.flat or md.block_m is None:
        return None
    override = _OVERRIDE.get(n_tokens)
    if override is not None:
        if md.output_aux:
            return None
        md = _kernels_transform(override, False, md)
    bm = int(md.block_m)
    if md.output_aux:
        if fm._MOE_SORT_BACKEND in ("opus", "ck") or bm != 16:
            return None
        if not fm.parse_g2_kname_any(md.stage2.keywords.get("kernelName2", ""))["atomic"]:
            return None
        aux = _AUX_OVERRIDE.get(n_tokens)
        if aux is not None:
            md = _kernels_transform(("aux",) + aux, False, md)
            if not fm.parse_g2_kname_any(md.stage2.keywords.get("kernelName2", ""))["atomic"]:
                return None
        return "aux", bm, q_dtype_a, None if aux is None else ("aux",) + aux
    if fm._USE_CK_MOE_SORTING or fm._USE_FLYDSL_MOE_SORTING:
        return None
    if not fm.stage2_uses_route_reduce(md.stage2):
        return "atomic", bm, q_dtype_a, override
    s2 = md.stage2
    if (
        n_tokens in _FP4_REDUCE
        and getattr(s2, "func", None) is fm._flydsl_v2_stage2_wrapper
        and not s2.args
        and (fm.parse_flydsl_v2_gemm2_kernel(s2.keywords.get("kernelName", "")) or {}).get("epilog")
        == "reduce"
    ):
        return "reduce_fp4", bm, q_dtype_a, override
    return "reduce", bm, q_dtype_a, override


def _aiter_into_out(plan, hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, out):
    """aiter's two-stage fused MoE with ``out`` as its accumulator (no output copy)."""
    import aiter
    from aiter import ActivationType, QuantType
    from aiter import fused_moe as fm
    from aiter.fused_moe import GateMode

    branch, bm, q_dtype_a, override = plan
    dev = hidden_states.device
    M = topk_ids.shape[0]
    i32 = torch.int32
    m_indices = reverse_sorted = a1_scale = split = einfo = None
    gather = 0
    if branch == "aux":
        active = min(257, M * _TOPK)
        max_sorted = (((M * _TOPK + active * (bm - 1)) + bm - 1) // bm) * bm
        sorted_ids = torch.empty(max_sorted, dtype=i32, device=dev)
        sorted_expert_ids = torch.empty(max_sorted // bm, dtype=i32, device=dev)
        num_valid_ids = torch.empty(2, dtype=i32, device=dev)
        sorted_weights = torch.empty(max_sorted, dtype=torch.float32, device=dev)
        reverse_sorted = torch.empty(M * _TOPK, dtype=i32, device=dev)
        m_indices = torch.empty(max_sorted, dtype=i32, device=dev)
        empty_bf16 = torch.empty((0,), dtype=torch.bfloat16, device=dev)
        aiter.mxfp4_moe_sort(
            topk_ids=topk_ids,
            topk_weight=topk_weights,
            sorted_token_ids=sorted_ids,
            sorted_expert_ids=sorted_expert_ids,
            cumsum_tensor=num_valid_ids,
            reverse_sorted=reverse_sorted,
            sorted_weights=sorted_weights,
            m_indices=m_indices,
            bf16_zero_out=out,
            bf16_zero_workspace=empty_bf16,
            sort3stage_ws=torch.empty(0, dtype=i32, device=dev),
            M_logical=M,
            NE=257,
            TOPK=_TOPK,
            D_HIDDEN=_D,
            D_INTER=1,
            MB=bm,
            prologue=0,
        )
    else:
        padded = M * _TOPK + 257 * bm - _TOPK
        sorted_ids = torch.empty(padded, dtype=i32, device=dev)
        sorted_weights = torch.empty(padded, dtype=torch.float32, device=dev)
        sorted_expert_ids = torch.empty((padded + bm - 1) // bm, dtype=i32, device=dev)
        num_valid_ids = torch.empty(2, dtype=i32, device=dev)
        if M in _ROUTE:
            C, Z = _ROUTE[M]
            Q = _ROUTE_QUANT.get(M, 0)
            gather = _S1_GATHER.get(M, 0) if Q else 0
            if Q:
                a1 = torch.empty((M, _D // 2), dtype=aiter.dtypes.fp4x2, device=dev)
                a1_scale = torch.empty((M, _D // 32), dtype=aiter.dtypes.fp8_e8m0, device=dev)
                qargs = (hidden_states.data_ptr(), a1.data_ptr(), a1_scale.data_ptr())
                hidden_states = a1
            else:
                qargs = (0, 0, 0)
            ts = _S1_SPLIT.get(M, 0) if Q and M in _S1_VALID_BOUND else 0
            es = _AUX_ES if branch == "reduce_fp4" else 0
            if ts or es:
                aux = torch.empty(_AUX_ES + (4 * _NE if es else 0), dtype=i32, device=dev)
            if es:
                einfo = aux[es:]
            _route_kernel(M, bm, C, Z if branch == "atomic" else 0, Q, gather, ts, es)(
                topk_ids.data_ptr(),
                topk_weights.data_ptr(),
                sorted_ids.data_ptr(),
                sorted_weights.data_ptr(),
                sorted_expert_ids.data_ptr(),
                num_valid_ids.data_ptr(),
                out.data_ptr(),
                *qargs,
                aux.data_ptr() if ts or es else 0,
                torch.cuda.current_stream(dev).cuda_stream,
            )
            if ts:
                # Without the gather, the head launch also re-sorts the scales into aiter's sorted layout.
                nt = 0 if gather else (padded + 31) // 32
                split = (aux, ts, a1_scale, num_valid_ids, nt, gather)
                if not gather:
                    a1_scale = torch.empty((nt * 32, _SCR), dtype=aiter.dtypes.fp8_e8m0, device=dev)
        else:
            moe_buf = out if branch == "atomic" else torch.empty((0, 0), dtype=torch.bfloat16, device=dev)
            ws_size = aiter.moe_sorting_opus_get_workspace_size(M, 257, _TOPK, 0)
            workspace = torch.empty(ws_size, dtype=torch.uint8, device=dev) if ws_size > 0 else None
            aiter.moe_sorting_opus_fwd(
                topk_ids,
                topk_weights,
                sorted_ids,
                sorted_weights,
                sorted_expert_ids,
                num_valid_ids,
                moe_buf,
                257,
                bm,
                None,
                None,
                workspace,
                0,
                None,
                None,
                None,
            )
    fp4 = branch == "reduce_fp4"
    presorted = gather or split is not None
    (_fused_moe_2stages_presorted() if presorted else fm.fused_moe_2stages)(
        hidden_states,
        w1,
        w2,
        _TOPK,
        sorted_ids,
        sorted_weights,
        sorted_expert_ids,
        num_valid_ids,
        out,
        True,
        bm,
        activation=ActivationType.Silu,
        quant_type=QuantType.per_1x32,
        doweight_stage1=False,
        q_dtype_a=q_dtype_a,
        q_dtype_w=w1.dtype,
        w1_scale=w1_scale,
        w2_scale=w2_scale,
        a1_scale=a1_scale,
        topk_ids=topk_ids,
        topk_weights=topk_weights,
        gate_mode=GateMode.SEPARATED,
        m_indices=m_indices,
        reverse_sorted=reverse_sorted,
        _metadata_transform=(
            functools.partial(
                _kernels_transform,
                override,
                fp4,
                vb=M in _S1_VALID_BOUND,
                gather=gather,
                split=split,
                es=einfo,
            )
            if fp4 or override is not None or gather
            else None
        ),
        _stage2_extra_args={"topk_weights": topk_weights} if fp4 else None,
    )


def run(
    *,
    hidden_states,
    w1,
    w2,
    topk_weights,
    topk_ids,
    w1_scale,
    w2_scale,
    activation,
    quant_type,
    doweight_stage1,
    gate_mode,
    act_quant,
    expert_mask,
    beta,
    linear_beta,
    out_dtype,
    out,
):
    n_tokens = hidden_states.shape[0]
    launch = _plan(n_tokens)
    if launch is not None:
        P = _DECODE[n_tokens][2]
        inter = (
            torch.empty((n_tokens * _TOPK, _I), dtype=torch.bfloat16, device=hidden_states.device)
            if P == 1
            else torch.empty((n_tokens * _TOPK * P, _N1), dtype=torch.bfloat16, device=hidden_states.device)
        )
        launch(
            hidden_states.data_ptr(),
            topk_ids.data_ptr(),
            w1.data_ptr(),
            w1_scale.data_ptr(),
            w2.data_ptr(),
            w2_scale.data_ptr(),
            topk_weights.data_ptr(),
            out.data_ptr(),
            inter.data_ptr(),
            torch.cuda.current_stream(hidden_states.device).cuda_stream,
        )
        return
    if (
        activation == "silu"
        and quant_type == "per_1x32"
        and not doweight_stage1
        and gate_mode == "separated"
        and expert_mask is None
        and beta is None
        and linear_beta is None
        and act_quant == 4
        and out.dtype == torch.bfloat16
        and out.is_contiguous()
        and topk_ids.dtype == torch.int32
        and topk_weights.dtype == torch.float32
        and topk_ids.is_contiguous()
        and topk_weights.is_contiguous()
        and out_dtype in (None, torch.bfloat16)
        and hidden_states.dtype == torch.bfloat16
    ):
        shuffled = bool(getattr(w1, "is_shuffled", False) and getattr(w2, "is_shuffled", False))
        plan = _aiter_plan(n_tokens, w1.dtype, shuffled)
        if plan is not None:
            _aiter_into_out(plan, hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, out)
            return
    result = fused_moe_baseline(
        hidden_states,
        w1,
        w2,
        topk_weights,
        topk_ids,
        expert_mask=expert_mask,
        activation=activation,
        quant_type=quant_type,
        doweight_stage1=doweight_stage1,
        w1_scale=w1_scale,
        w2_scale=w2_scale,
        beta=beta,
        linear_beta=linear_beta,
        gate_mode=gate_mode,
        out_dtype=out_dtype,
        act_quant=act_quant,
    )
    out.copy_(result)
